    for(let y=Math.floor(cy-ry-1);y<=cy+ry+1;y++)for(let x=Math.floor(cx-rx-1);x<=cx+rx+1;x++)if(Math.hypot((x-cx)/rx,(y-cy)/ry)<1+r()*.35&&[50,52,53,57].includes(at(x,y)))set(x,y,54);
