function isRecord(x){return !!x&&typeof x==='object'&&!Array.isArray(x)}
function clampNumber(x,min,max,fallback){return Number.isFinite(+x)?Math.max(min,Math.min(max,+x)):fallback}
function cleanRecords(x){const out={};if(isRecord(x))for(const m of ['s','a'])for(let c=1;c<=6;c++){const k=m+c,r=x[k];if(!isRecord(r))continue;const q={t:clampNumber(r.t,0,86400,0),lvl:Math.floor(clampNumber(r.lvl,1,999,1)),kills:Math.floor(clampNumber(r.kills,0,1e7,0))};if(Number.isFinite(+r.win)&&+r.win>0)q.win=clampNumber(r.win,1,86400,720);out[k]=q}return out}try{const q=+localStorage.getItem('pn_bri');if(q>=.7&&q<=1.6)SETT.bri=q}catch(e){}postMat.uniforms.bri.value=SETT.bri;
try{const v=JSON.parse(localStorage.getItem('pn_access')||'{}');if(isRecord(v)){if([.9,1,1.15,1.3].includes(v.ts))SETT.ts=v.ts>1?1:v.ts;/* 16.11.2026: tylko dwa rozmiary: .9 (Normalny) i 1 (Duzy) */for(const k of ['shake','rumble','flash','contrast','oneHand','hiRes','fpsShow'])if(typeof v[k]==='boolean')SETT[k]=v[k];if(['low','high'].includes(v.quality))SETT.quality=v.quality;if(v.kam==='k'||v.kam==='p')SETT.kam=v.kam;SETT.qmode=['auto','ultra','high','mid','min'].includes(v.qmode)?v.qmode:(v.quality==='low'?'mid':v.quality==='high'?'high':'auto');if([30,45,60,120].includes(+v.fpsCap))SETT.fpsCap=+v.fpsCap;{const gv=(k,ok)=>{if(v[k]==='auto')SETT[k]='auto';else if(ok.includes(+v[k]))SETT[k]=+v[k]};gv('gShadow',[0,1,2]);gv('gLights',[2,4,10]);gv('gFx',[0,1,2]);gv('gParts',[.5,1,1.5]);gv('gRes',[540,720,1080,1440,2160]);gv('gDpr',[1,1.5,2]);gv('gTex',[0,1]);if(['auto','on','off'].includes(v.gDyn))SETT.gDyn=v.gDyn;if(v.hiRes===true&&SETT.gRes==='auto')SETT.gRes=720;SETT.hiRes=false}}}catch(e){quietErr('loadAccess',e)}
