function pumpNotice(){if(!S||S.phase!=='play'||S.notice||S.intro||S.dialog||S.choosing||S.shop||S.paused)return;if(S.witRewardPending&&S.pendLv>0&&!S.banner&&!(S.noticeQueue||[]).length){S.witRewardPending=false;openLevelUp()}}
