function updatePowerVisuals(){fireFxTick();roofTick();if(!S)return;loopSnd('pot','Kociolek',clock-(S.potHealT||-9)<.25?.7:0);for(const f of W.fireMarkers||[]){const armed=S.rebirth&&S.rebirth.ch===CH&&S.rebirth.index===f.index;f.mesh.material.color.setHex(S.rebirthUsed||S.rebirth&&!armed?0x766b65:armed?0x8cead4:0xffad55);f.mesh.material.opacity=(S.rebirthUsed||S.rebirth&&!armed)?.18:armed?.85:(.48+.18*Math.sin(clock*2))*(W.pot3d?.7:1);{const pv=S.pot&&S.pot[CH+':'+f.index];if(pv!=null&&pv<=0){f.mesh.material.color.setHex(0x555555);f.mesh.material.opacity=.15}}if(S.fxHeal!=null&&f.index===S.fxHealIdx&&clock-S.fxHeal<.25){f.mesh.material.color.setHex(0x9dffc0);f.mesh.material.opacity=.95;f.mesh.scale.setScalar(1.15+.12*Math.sin(clock*8))}else f.mesh.scale.setScalar(1)}for(const p of S.deathPurses||[]){p.mesh.visible=p.ch===CH;p.mesh.position.set(p.x/16,.2+Math.sin(clock*3)*.035,p.y/16)}}
function recoverPurses(){for(let i=(S.deathPurses||[]).length-1;i>=0;i--){const p=S.deathPurses[i];if(p.ch!==CH)continue;const distance=Math.hypot(pl.x-p.x,pl.y-p.y);if(!p.ready){if(distance>24)p.ready=true;continue}if(distance>16)continue;S.coins+=p.amount;scene.remove(p.mesh);S.deathPurses.splice(i,1);play('purse',0);say((EN?'You recover the purse from where you died: ':'Odzyskujesz sakwę z miejsca śmierci: ')+p.amount+(EN?' coins.':' monet.'))}}
