function dzwClear(){for(const m of DZW_MESH)scene.remove(m);DZW_MESH.length=0;if(S){S.echoes=[];S.echoArm=0;S.pledge=0;S.pledgeT=0;S.pledgeHv=0;S.pledgeHvT=0}}
