function milClear(){if(!S)return;if(S.effigy&&S.effigy.f)S.effigy.f.t=S.effigy.f.dur;S.effigy=null;S.gut=null;S.wick=0;S.milStrips=[];if(pl){pl.milEffT=0;if(pl.atk?.kind==='gut')pl.atk=null}}
