  let mx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+tj.x+PAD.x,my=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+tj.y+PAD.y;
