const charId=()=>{try{return prog().char||'r'}catch(e){return 'r'}};
const katOn=()=>charId()==='k';
const zabOn=()=>charId()==='z';
const dzwOn=()=>charId()==='d';
const milOn=()=>charId()==='m';
// Wspólne dane bohaterów (12.11.2026): jedno źródło imienia, przydomka i klasy dla całego interfejsu. ID techniczne (r,k,z,d,m) bez zmian.
const HEROES={r:{n:'Hadræn',ep:EN?'the Crestless':'Bez Herbu',cls:EN?'Knight':'Rycerz',art:'rycerz',mot:(EN?'“I have stood at more than one gate for another man\'s gold. I came too late to this one. I will at least check whether anyone was left behind the doors.”':'„Za cudze złoto stałem już przy niejednej bramie. Do tej przyszedłem za późno. Sprawdzę choć, czy ktoś został za drzwiami.”')},k:{n:'Goran',ep:EN?'the Neckbreaker':'Łamacz Karków',cls:EN?'Executioner':'Kat',art:'kat',mot:(EN?'“All my life I waited for someone to read out the sentence. I want to look once into the eyes of the one who signed it.”':'„Całe życie czekałem, aż ktoś przeczyta wyrok. Chcę raz spojrzeć w oczy temu, kto go podpisał.”')},z:{n:'Mira',ep:EN?'the Ash Dancer':'Tancerka Popiołów',cls:EN?'Ash Dancer':'Tancerka Popiołu',art:'zabojczyni',mot:(EN?'“I went around their posts. I will slip away on my own. But what do I tell those inside if they ask the way?”':'„Obeszłam ich posterunki. Sama się wymknę. Tylko co powiem tym w środku, jeśli spytają o drogę?”')},d:{n:'Iwo',ep:EN?'the Herald of Silence':'Zwiastun Ciszy',cls:EN?'Bellringer':'Dzwonnik',art:'dzwonnik',mot:(EN?'“I tolled for the dead. Now they follow me. I will stay until one of them can finally rest.”':'„Dzwoniłem za zmarłych. Teraz idą za mną. Zostanę, aż któryś wreszcie będzie mógł odpocząć.”')},m:{n:'Milena',ep:EN?'the Unquenched':'Niedogasła',cls:EN?'Candlebound':'Woskownica',art:'woskownica',mot:(EN?'“I carried light to the granary. Too late. I still have a wick left. It will be of use underground.”':'„Niosłam światło do spichlerza. Za późno. Został mi jeszcze knot. Przyda się pod ziemią.”')}};
// przydomek z Kaplicy zastępuje stały przydomek bohatera (getter: EMB może jeszcze nie istnieć przy starcie)
for(const c in HEROES){const base=HEROES[c].ep;Object.defineProperty(HEROES[c],'ep',{get(){try{return titleOn()||base}catch(e){return base}},enumerable:true,configurable:true})}
const heroName=(c,full)=>{const h=HEROES[c]||HEROES.r;return full?h.n+', '+h.ep:h.n};
