const perkMinus=p=>p.mi;
const PREP={perks:[],ch:null},PNEED=l=>150+75*(l-1),PMAX=10,PMODE=()=>'s';
// 15.11.2026: poziom maksymalny (10) daje drugi slot perka
const perkSlots=q=>q&&q.lv>=PMAX?2:1;
function perkToggle(q,id){const i=PREP.perks.indexOf(id);if(i>=0)PREP.perks.splice(i,1);else{const n=perkSlots(q);PREP.perks=n>1?[...PREP.perks,id].slice(-n):[id]}q.sel=PREP.perks.slice()}
function cleanProg(raw){const o={};for(const m of ['s','a']){const q=isRecord(raw)&&isRecord(raw[m])?raw[m]:{};const lv=Math.floor(clampNumber(q.lv,1,PMAX,1));o[m]={lv,xp:lv>=PMAX?0:Math.floor(clampNumber(q.xp,0,PNEED(lv)-1,0)),sel:[...new Set(Array.isArray(q.sel)?q.sel:[])].filter(id=>PERKS.some(p=>p.id===id&&p.lv<=lv)).slice(0,lv>=PMAX?2:1),ch:CHALS.some(c=>c.id===q.ch)?q.ch:null,bank:Math.floor(clampNumber(q.bank,0,999,0)),char:['k','z','d','m'].includes(q.char)?q.char:'r'}}return o}
function loadProg(){try{return cleanProg(JSON.parse(localStorage.getItem('pn_prog')||'{}'))}catch(e){return cleanProg({})}}
const PROG=loadProg();function saveProg(){try{localStorage.setItem('pn_prog',JSON.stringify(PROG))}catch(e){warnSaveFailure()}}
const prog=()=>PROG[PMODE()];
