$('confNo').addEventListener('click',()=>{$('conf').hidden=true;$('opts').hidden=false;setTimeout(()=>$('clearSave').focus(),30)});
$('confYes').addEventListener('click',()=>{SETT.save={};saveStore();for(const m of ['s','a'])Object.assign(PROG[m],{xp:0,lv:1,sel:[],ch:null,char:'r'});saveProg();Object.assign(META,cleanMeta({}));saveMeta();renderRecords();refreshDat();$('conf').hidden=true;$('opts').hidden=false;$('clearSave').textContent=(EN?'Save cleared':'Zapis wyczyszczony');setTimeout(()=>{$('clearSave').textContent=(EN?'Clear progress save':'Wyczyść zapis postępu')},1800)});

// ============ META (8.11.2026): medals, chronicle, bestiary, night of the week, curses ============
// Own save key pn_meta; never touches pn_prog / pn_embers except granting Ashes (EMB.e).
function cleanMeta(r){r=isRecord(r)?r:{};const num=(v,mx=1e9)=>Math.floor(clampNumber(v,0,mx,0)),obj=o=>isRecord(o)?o:{};const med={},kr={},kills={},st={},nm={};
  for(const k in obj(r.med))if(/^[rkzdm][1-5]$/.test(k))med[k]=num(r.med[k],3);for(const k in obj(r.kr))if(/^[\w-]{1,40}$/.test(k)&&r.kr[k])kr[k]=1;
  for(const k in obj(r.kills))if(/^\w{1,30}$/.test(k))kills[k]=num(r.kills[k]);for(const k in obj(r.nm))if(/^\w{1,30}$/.test(k))nm[k]=num(r.nm[k]);const notes={};for(const k in obj(r.notes))if(/^\w{1,30}$/.test(k)&&r.notes[k])notes[k]=1;const endl={};for(const k in obj(r.endl))if(/^[1-5]$/.test(k))endl[k]=num(r.endl[k]);for(const k of ['kills','nights','wins','chals','parries','ash','winR','winK','winZ','winD','winM','time','nR','nK','nZ','nD','nM','tR','tK','tZ','tD','tM','hits','dmg','deaths'])st[k]=num(obj(r.st)[k]);const sku={};for(const k in obj(r.sku))if(/^[rkz]:\w{1,30}$/.test(k))sku[k]=num(r.sku[k]);
  const w=obj(r.wk),y=obj(r.dy),ss=v=>typeof v==='string'?v.slice(0,12):'';const sn=isRecord(r.sn)?(()=>{const o={};for(const k in r.sn)if(/^[aben]:[\w-]{1,40}$/.test(k))o[k]=1;return o})():null;return{v:1,sn,med,kr,kills,nm,sku,endl,notes,st,wk:{done:ss(w.done),key:ss(w.key),best:num(w.best)},dy:{done:ss(y.done),key:ss(y.key),best:num(y.best),streak:num(y.streak,9999),top:num(y.top,9999)},bst:(()=>{const o={};for(const k in obj(r.bst))if(/^(?:[1-5]|dg)$/.test(k)){const v=obj(r.bst[k]);o[k]={kills:num(v.kills),streak:num(v.streak),hit:num(v.hit),dmg:num(v.dmg),eli:num(v.eli)}}return o})()}}
const META=(()=>{try{return cleanMeta(JSON.parse(localStorage.getItem('pn_meta')||'{}'))}catch(e){return cleanMeta({})}})();
// 10.11.2026: "new" marks in the Chronicle. META.sn = entries the player has already looked at;
// on the first run everything unlocked so far counts as seen, so old saves do not light up.
function kronUnl(){const o=[];for(const k of KRON)if(META.kr[k[0]])o.push('a:'+k[0]);for(const t in META.kills)if(META.kills[t]>0&&t!=='glizzard'&&ENAME[t])o.push('b:'+t);for(const k in META.nm)if(META.nm[k]>0)o.push('e:'+k);for(const k in (META.notes||{}))o.push('n:'+k);return o}
function kronNew(){if(!META.sn){META.sn={};for(const k of kronUnl())META.sn[k]=1;saveMeta()}return kronUnl().filter(k=>!META.sn[k])}
function kronNewCss(){if($('nbkNewCss'))return;const st=document.createElement('style');st.id='nbkNewCss';st.textContent='.nbk-new{display:inline-block!important;margin-left:.55em;padding:.08em .5em;font:700 .6em/1.35 Georgia,serif!important;letter-spacing:.1em;font-style:normal!important;color:#1a1208!important;background:#e8c25a;border-radius:2px;vertical-align:middle;text-shadow:none!important}.m2k-row .nbk-new{position:absolute!important;top:.75em;right:.95em;margin:0!important;font-size:12px!important}#kronBtn .nbk-new{position:absolute!important;top:3px;right:9px;margin:0!important;padding:0 .45em!important;font-size:11px!important;z-index:2}.nbk-dot{display:inline-block!important;width:.5em;height:.5em;margin-left:.45em;border-radius:50%;background:#e8c25a;box-shadow:0 0 6px #e8c25a;vertical-align:middle}';document.head.appendChild(st)}
