function padLostMsg(on){let n=$('padLost');if(!on){if(n)n.hidden=true;return}const rb=$('resumeBtn');if(!rb||!rb.parentNode||!rb.parentNode.parentNode)return;if(!n){n=document.createElement('p');n.id='padLost';n.setAttribute('role','status');n.style.cssText='margin:0 0 .6em;padding:.45em .9em;text-align:center;border:1px solid #7a5a24;background:#1c1610;color:#f0d9a8;font-weight:600;font-size:15px;line-height:1.3';rb.parentNode.parentNode.insertBefore(n,rb.parentNode)}n.textContent=EN?'Controller disconnected. Game paused.':'Pad rozłączony. Gra zatrzymana.';n.hidden=false}
function togglePause(on){if(!S||S.phase!=='play'||S.notice||S.choosing||S.shop||S.dialog||S.intro)return;const wasP=!!S.paused;S.paused=on===undefined?!S.paused:on;if(wasP!==!!S.paused)uiSnd(S.paused?'pauseIn':'pauseOut');pauseQuitAsk(false,1);if(!S.paused)padLostMsg(false);if(S.paused){fillPauseKeys();renderLoadout();trnFill();pl.swingT=0}trainBox();renderActiveHud();$('pause').hidden=!S.paused;
  for(const k in keys)keys[k]=false;resetInput();if(AC){if(S.paused&&AC.state==='running')AC.suspend();else if(!S.paused&&AC.state==='suspended')acResume()}if(S.paused)setTimeout(()=>$('resumeBtn').focus(),30)}
