let quitAsk=null;function pauseQuitAsk(on){const row=$('pauseMenuBtn').parentNode;if(!quitAsk){if(!on)return;quitAsk=document.createElement('div');quitAsk.id='pauseQuit';quitAsk.className='btnrow';quitAsk.setAttribute('role','alertdialog');quitAsk.innerHTML=`<p>${EN?'Abandon this night? Its progress will be lost.':'Porzucić tę noc? Jej postęp przepadnie.'}</p><button type="button" class="go" id="pauseQuitNo">${EN?'Stay':'Zostań'}</button><button type="button" class="go alt" id="pauseQuitYes">${EN?'Abandon night':'Porzuć noc'}</button>`;row.after(quitAsk);$('pauseQuitNo').addEventListener('click',()=>pauseQuitAsk(false));$('pauseQuitYes').addEventListener('click',()=>{pauseQuitAsk(false,1);toMenu()})}quitAsk.hidden=!on;row.hidden=!!on;if(arguments[1])return;setTimeout(()=>{const f=on?$('pauseQuitNo'):$('pauseMenuBtn');if(f&&f.offsetParent!==null)f.focus()},30)}
