addEventListener('keydown',e=>{if(S&&S.notice){e.stopImmediatePropagation();e.preventDefault();if(!e.repeat&&['Enter',' ','e','Escape'].includes(e.key))dismissNotice();return}if(S&&S.witChoice&&['1','2','3','4','Enter',' '].includes(e.key)){e.preventDefault();e.stopImmediatePropagation();if(e.repeat)return;if('1234'.includes(e.key))chooseNpc(+e.key-1);else if(document.activeElement.closest&&document.activeElement.closest('#witChoices'))document.activeElement.click()}},true);
