   if(x1>x0&&y1>y0){const side=Math.max(x1-x0,(y1-y0)*.74)*1.1;g.imageSmoothingEnabled=false;g.drawImage(frame,(x0+x1-side)/2,y0-side*.035,side,side,0,0,192,192)}
